  ('antigua-guatemala', '10S', 'Antigua', 'Guatemala', 'Colonial streets under two volcanoes **TravelWell', 'live', 'verified', 'kyoto', 'Guatemala', '{"expedition","culture","culinary","wildlife"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["UNESCO World Heritage colonial city (16th-18th c. Spanish architecture) cradled beneath Volcanoes Agua, Fuego and Acatenango.","Base for the Acatenango overnight trek (summit 3,976 m) with front-row views of continuously erupting Fuego; Pacaya (2,552 m) is the gentler guided lava hike.","Semana Santa is the most famous Holy Week in the Americas - dawn processions over colored-sawdust alfombras; books ~1 year ahead on tiny inventory.","Premier coffee origin: Finca Filadelfia (est. 1870) and nonprofit De la Gente run finca-to-cup tours minutes from the plaza.","A rising colonial-wedding and honeymoon destination anchored by converted-palace boutique hotels (Casa Santo Domingo, Palacio de Dona Leonor, Pensativo House)."],"safety":{"emergency":"110 police (PNC) / 122-123 bomberos (fire-rescue) / 128 Cruz Roja ambulance / 1500 PROATUR tourist assistance; Antigua POLITUR tourist police","hospital":"Hospital Nacional Pedro de Bethancourt (Antigua) + private clinics for stabilization; major trauma/evac to Guatemala City ~1 hr","book_enabled":true,"l3_disclosure":true,"state_dept_carveout":"Antigua/Sacatepequez explicitly cleared; avoid San Marcos/Huehuetenango/Zone-18/Villa Nueva","stay_in_zone":true,"air_access_verified":true,"altitude":"Antigua ~1,500 m (mild); Acatenango summit 3,976 m = serious AMS; Pacaya ~2,552 m","water":"bottled/purified only","malaria":"no malaria risk in Antigua (highland); dengue/Zika precaution advised","consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"}},"timing":{"inflection_curve_start":"peak dry season Nov-Mar (baseline); Feb is the sweet spot (crowds dip, dry)","peak":"Semana Santa (Holy Week) late Mar/early Apr - THE event; 2027 ~Mar 24-28 (Good Friday Mar 26)","fire_date":"general dry-season curve: fire ~mid-October (curve-start -1-2 wks); Semana Santa 2027: fire ~Apr-May 2026 (~1 yr ahead), last-call ''book by January''","shoulder":"late Oct-Nov & Feb (dry, thinner crowds, easier rates)","green":"May-Oct wet season (lower rates; Sep-Oct wettest but quietest/cheapest)","booking_lead":"Semana Santa ~1 year; weddings 9-12 months; general dry-season 2-3 months","off_season_specials":"wet-months ''quiet Antigua'' value: coffee-finca/roasting tours, jade & textile workshops, cooking classes, Casa Santo Domingo museums + spa, guided treks with flexible dates","event_peaks":["Semana Santa (late Mar/early Apr)","Sumpango Barriletes Gigantes giant-kite festival (Nov 1, All Saints)","Christmas/New Year"]},"jewels":[{"name":"Acatenango sunrise-over-Fuego overnight","si_tag":"Global Expedition Adventures","status":"live","hook":"Guided overnight ridge camp at ~3,500 m watching Fuego erupt through the night and sunrise over the highlands.","bookable_category":"guided overnight trek (guided-only)","tier":"premier","commission_path":"DMC 10-12% / Viator-GetYourGuide 4-8%; park + guide fees pass-through","source":"https://www.muchbetteradventures.com/magazine/acatenango-volcano-hike-guide/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Guided overnight ridge camp at ~3,500 m watching Fuego erupt through the night and sunrise over the highlands.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / Viator-GetYourGuide 4-8%; park + guide fees pass-through"},{"name":"Pacaya lava hike + marshmallows","si_tag":"Global Expedition Adventures","status":"live","hook":"Shorter guided hike to warm volcanic ground near active Pacaya; family-friendly acclimatizer.","bookable_category":"guided day hike","tier":"essential","commission_path":"affiliate 4-8% / DMC 10-12%; park fee pass-through","source":"https://theworldtravelguy.com/acatenango-hike-volcan-de-fuego/","si":"expedition","blurb":"Shorter guided hike to warm volcanic ground near active Pacaya; family-friendly acclimatizer.","commission":"affiliate 4-8% / DMC 10-12%; park fee pass-through"},{"name":"Semana Santa alfombras + processions","si_tag":"Culture & Heritage","status":"future","hook":"Dawn Good Friday La Merced procession over street carpets of colored sawdust and flowers - the most famous Holy Week in the Americas.","bookable_category":"event + hotel/DMC room block","tier":"premier","commission_path":"hotel/DMC AOR; event pass-through; book ~1 yr ahead","source":"https://livinginguatemala.com/events/semana-santa-guatemala/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Dawn Good Friday La Merced procession over street carpets of colored sawdust and flowers - the most famous Holy Week in the Americas.","when":"Semana Santa  late Mar/early Apr","commission":"hotel/DMC AOR; event pass-through; book ~1 yr ahead"},{"name":"Cerro de la Cruz viewpoint","si_tag":"Culture & Heritage","status":"future","hook":"Hilltop cross with the classic Antigua panorama framed by Volcan Agua.","bookable_category":"free / guided city tour","tier":"essential","commission_path":"bundled into commissionable city tour","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Hilltop cross with the classic Antigua panorama framed by Volcan Agua.","when":"year-round","commission":"bundled into commissionable city tour"},{"name":"Santo Domingo del Cerro sculpture park","si_tag":"Culture & Heritage","status":"future","hook":"Hilltop art-and-garden annex above Casa Santo Domingo with city + volcano views; free hotel shuttle.","bookable_category":"free / hotel shuttle add-on","tier":"essential","commission_path":"pairs with Casa Santo Domingo stay (hotel AOR)","source":"https://www.casasantodomingo.com.gt/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Hilltop art-and-garden annex above Casa Santo Domingo with city + volcano views; free hotel shuttle.","when":"Semana Santa  late Mar/early Apr","commission":"pairs with Casa Santo Domingo stay (hotel AOR)"},{"name":"Jade museum + workshop","si_tag":"Culture & Heritage","status":"future","hook":"Working jade ateliers demonstrating Guatemala''s Maya jade tradition; high-margin retail tie-in.","bookable_category":"guided artisan tour","tier":"premier","commission_path":"artisan-tour affiliate; retail non-commissionable","source":"https://www.dlgcoffee.org/coffee-tour","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Working jade ateliers demonstrating Guatemala''s Maya jade tradition; high-margin retail tie-in.","when":"year-round","commission":"artisan-tour affiliate; retail non-commissionable"},{"name":"Chichicastenango market day-trip","si_tag":"Culture & Heritage","status":"future","hook":"Thursday/Sunday highland Maya market of textiles and masks.","bookable_category":"DMC day tour (cleared corridor)","tier":"comfort","commission_path":"DMC 10-12% / affiliate 4-8%","source":"https://www.martsam.com/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Thursday/Sunday highland Maya market of textiles and masks.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / affiliate 4-8%"},{"name":"Ciudad Vieja (first colonial capital)","si_tag":"Culture & Heritage","status":"future","hook":"Guatemala''s original 1527 capital, destroyed by a 1541 lahar, just outside Antigua - deep-history layer.","bookable_category":"guided cultural add-on","tier":"essential","commission_path":"bundled into commissionable heritage tour","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Guatemala''s original 1527 capital, destroyed by a 1541 lahar, just outside Antigua - deep-history layer.","when":"Semana Santa  late Mar/early Apr","commission":"bundled into commissionable heritage tour"},{"name":"Finca Filadelfia coffee tour","si_tag":"Culinary","status":"future","hook":"Finca-to-cup tour on an 1870-founded estate, one of Guatemala''s first coffee farms; ~$20, on-site hotel + restaurant.","bookable_category":"coffee-finca tour (direct/Viator)","tier":"comfort","commission_path":"Viator affiliate 4-8%; direct pass-through","source":"https://www.visit-antigua.com/finca-filadelfia.php","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Finca-to-cup tour on an 1870-founded estate, one of Guatemala''s first coffee farms; ~$20, on-site hotel + restaurant.","when":"Semana Santa  late Mar/early Apr","commission":"Viator affiliate 4-8%; direct pass-through"},{"name":"De la Gente community coffee tour","si_tag":"Culinary","status":"future","hook":"Nonprofit farmer-led tour in San Miguel Escobar (~4 hr, ~$38 incl. shuttle + beans) - responsible-tourism moat.","bookable_category":"community coffee tour","tier":"essential","commission_path":"affiliate/donation model; largely pass-through - brand-values proof point","source":"https://www.dlgcoffee.org/coffee-tour","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Nonprofit farmer-led tour in San Miguel Escobar (~4 hr, ~$38 incl. shuttle + beans) - responsible-tourism moat.","when":"Semana Santa  late Mar/early Apr","commission":"affiliate/donation model; largely pass-through - brand-values proof point"},{"name":"Guatemalan cooking class","si_tag":"Culinary","status":"future","hook":"Hands-on colonial-kitchen class (pepian, tamales, tortillas); rainy-day-proof culinary depth.","bookable_category":"Viator/GetYourGuide class","tier":"comfort","commission_path":"affiliate 4-8%","source":"https://www.getyourguide.com/antigua-guatemala-l1619/from-antigua-or-guatemala-coffee-culture-full-day-tour-t21818/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Hands-on colonial-kitchen class (pepian, tamales, tortillas); rainy-day-proof culinary depth.","when":"Semana Santa  late Mar/early Apr","commission":"affiliate 4-8%"},{"name":"Sumpango Barriletes Gigantes giant-kite festival","si_tag":"Wildlife & Nature","status":"future","hook":"40-ft+ handmade kites flown in the cemetery on All Saints'' Day (Nov 1) to commune with the dead.","bookable_category":"DMC day tour (Nov 1 only)","tier":"comfort","commission_path":"DMC 10-12% / affiliate 4-8%; entry pass-through","source":"https://tropicanahostel.com/antigua-weather-what-to-expect-and-the-best-time-to-visit/","timing":"Semana Santa  late Mar/early Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","blurb":"40-ft+ handmade kites flown in the cemetery on All Saints'' Day (Nov 1) to commune with the dead.","when":"Semana Santa  late Mar/early Apr","commission":"DMC 10-12% / affiliate 4-8%; entry pass-through"}],"faq":[{"q":"How hard is the Acatenango overnight volcano trek?","a":"It''s a serious guided overnight — roughly 1,570 m of ascent to a 3,976 m summit over a 10–12-hour trek split across two days, with base camp near 3,500 m. It''s worth it because you watch Fuego erupt through the night, but altitude and cold are real, so TWW sells reputable guided operators only.","source":"theworldtravelguy.com, Accessed 2026-07-06","si_tag":"expedition"},{"q":"Is Antigua a good place for a wedding or honeymoon?","a":"Yes — Antigua is a genuinely rising colonial-wedding city, because its converted-palace boutique hotels deliver character at the luxury-boutique level: Casa Santo Domingo (5-star, #11 of 102, 4.6★, 2,724 reviews), palace-suite Palacio de Doña Leonor, and adults-only 26-room Pensativo House. Colonial weddings book 9–12 months ahead.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"romance"},{"q":"When is Semana Santa 2027 and how far ahead should I book?","a":"Book about a year ahead. Semana Santa 2027 runs ~March 24–28 (Good Friday Mar 26), the most famous Holy Week in the Americas, and Antigua has limited hotel inventory — \"the best places sell out months in advance.\" Fire the booking a full year out, with a \"book by January\" last-call.","source":"livinginguatemala.com, Accessed 2026-07-06","si_tag":"culture"},{"q":"Can I tour a coffee farm from Antigua?","a":"Yes, minutes from the plaza. Finca Filadelfia — founded 1870 as one of Guatemala''s first coffee farms — runs ~2-hour finca-to-cup tours (~$20), and nonprofit De la Gente runs a ~4-hour farmer-led tour in San Miguel Escobar (~$38 incl. shuttle + beans), because Antigua is a premier coffee origin.","source":"visit-antigua.com, Accessed 2026-07-06","si_tag":"culinary"},{"q":"Does Antigua have spa and wellness options?","a":"Yes — the anchor is the 5-star Hotel Museo Spa Casa Santo Domingo, whose spa sits alongside six on-site museums inside 16th-century Dominican monastery ruins, making it Antigua''s iconic wellness-and-culture address. It''s a quiet colonial-retreat market rather than a resort-spa one.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"wellness"},{"q":"Can I see the giant-kite festival from Antigua?","a":"Yes, as a Nov 1 day-trip. The Sumpango Barriletes Gigantes festival flies 40-ft+ handmade kites in the cemetery on All Saints'' Day to commune with the dead — visually stunning and uniquely Guatemalan, an easy DMC day tour from Antigua.","source":"tropicanahostel.com, Accessed 2026-07-06","si_tag":"wildlife"},{"q":"Is Antigua Guatemala safe to visit right now?","a":"Yes, with mandatory disclosure. Guatemala is US Level 3 \"Reconsider Travel\" (reissued Jun 11, 2026; codes C + T), but the advisory explicitly clears Antigua for US-government employees; the Level 4 \"Do Not Travel\" zones — San Marcos, Huehuetenango, Zone 18 (Guatemala City), Villa Nueva — are elsewhere. Stay on the La Aurora–Antigua corridor.","source":"travel.state.gov, Accessed 2026-07-06","si_tag":"safety"},{"q":"What''s the real risk to plan for on Acatenango?","a":"Cold, not lava. Base-camp temperatures drop to 0 °C to −5 °C; on January 8, 2017, six Guatemalan hikers died of hypothermia on Acatenango after arriving unprepared — an exposure/preparation failure, not a lava event. Book only reputable guided operators who supply proper down layers, tents and a real sleeping system.","source":"theworldtravelguy.com, Accessed 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Antigua Guatemala Travel Guide 2026 — Volcanoes, Semana Santa & Colonial Weddings | TravelWell.World","meta_description":"Plan Antigua Guatemala: the Acatenango/Fuego overnight volcano trek (guided-only, 3,976 m), world-famous Semana Santa alfombras, coffee fincas, colonial-wedding hotels, and straight L3 State-Dept-cleared safety.","slug":"antigua-guatemala","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":["en","es-GT"],"local_keywords":["qué hacer en Antigua Guatemala","Acatenango tour","Semana Santa Antigua","bodas Antigua Guatemala","tour de café Antigua","volcán Pacaya Antigua","hoteles de lujo Antigua Guatemala","alfombras Semana Santa"],"hreflang":["en","es-GT"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"culinary","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Hotel Museo Spa Casa Santo Domingo","why_ultra":"5-star in 16th-c. Dominican monastery ruins; six museums + spa; #11 of 102 Antigua hotels; Antigua''s iconic top-of-market address","earning":"on application / host-Virtuoso or Fora where eligible","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"luxury"},{"name":"Palacio de Dona Leonor","why_ultra":"converted colonial palace, antique-furnished grand suites in the historic core; romance/honeymoon standout","earning":"on application / Fora lane where eligible","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"luxury"},{"name":"Pensativo House","why_ultra":"26-room adults-only boutique (Porta Hotels), garden + rooftop + spa, steps off Central Park; honeymoon fit","earning":"on application / Fora lane","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"luxury"}],"source_verified":"2026-07-06","hero":{"query":"Antigua, Guatemala"},"geo":{"lat":14.5586,"lng":-90.7295}}'::jsonb, 5),
